mapper.select:
SELECT MAX(version_no)
FROM mk_segment_definition
WHERE tenant_id = #{tenantId}
  AND segment_id = #{segmentId}

SELECT current.segment_id AS segmentId, current.version_no AS versionNo, current.name, current.state_name AS stateName, current.rule_json AS ruleJson, current.rule_hash AS ruleHash, current.created_at AS createdAt FROM mk_segment_definition current WHERE current.tenant_id = #{tenantId} AND current.version_no = ( SELECT MAX(latest.version_no) FROM mk_segment_definition latest WHERE latest.tenant_id = current.tenant_id AND latest.segment_id = current.segment_id ) AND current.segment_id > #{cursor}
AND ( LOCATE(CAST(LOWER(#{query}) AS BINARY), CAST(LOWER(current.name) AS BINARY)) > 0 OR LOCATE(CAST(LOWER(#{query}) AS BINARY), CAST(LOWER(current.segment_id) AS BINARY)) > 0 OR LOCATE(CAST(LOWER(#{query}) AS BINARY), CAST(LOWER(CAST(current.version_no AS CHAR)) AS BINARY)) > 0 OR LOCATE(CAST(LOWER(#{query}) AS BINARY), CAST(LOWER(current.rule_hash) AS BINARY)) > 0 OR LOCATE(CAST(LOWER(#{query}) AS BINARY), CAST(LOWER(current.state_name) AS BINARY)) > 0 OR LOCATE(CAST(LOWER(#{query}) AS BINARY), CAST(LOWER(CASE current.state_name WHEN 'ACTIVE' THEN '已生效' WHEN 'READY' THEN '已就绪' WHEN 'DRAFT' THEN '草稿' WHEN 'STALE' THEN '已过期' ELSE current.state_name END) AS BINARY)) > 0 OR LOCATE(CAST(LOWER(#{query}) AS BINARY), CAST(LOWER(DATE_FORMAT(DATE_ADD(STR_TO_DATE(SUBSTRING(current.created_at, 1, 19), '%Y-%m-%dT%H:%i:%s'), INTERVAL 8 HOUR), '%Y/%m/%d %H:%i:%s')) AS BINARY)) > 0 )
ORDER BY current.segment_id LIMIT #{fetchSize}

mapper.sql:
SELECT
    active_value AS activeValue,
    membership_version AS membershipVersion
FROM mk_audience_member
WHERE tenant_id = #{tenantId}
  AND snapshot_id = #{snapshotId}
  AND subject_hash = #{subjectHash}
